# -*- coding: utf-8 -*-
"""Lecture 45 vignette pool A -- mixed acid-base disorders (s23, s26-30), the Winter formula (s49), the change in
anion gap against the change in bicarbonate and the chloride check (s27, s50), with the albumin-corrected anion gap
(s8) worked inside mixed cases.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.
EXPLANATIONS follow tools/question_writing/EXPLAIN_DEEP.md: the key walks the arithmetic from the stem's values;
each wrong choice says why it fails for THIS patient, the replacing fact, and a "Tell:".

Held for the scope (cms_e7l45_scope.py):
  - every blood value carries its normal range; gap = sodium - (chloride + bicarbonate) is internally consistent and
    the pH of every gas was computed from its carbon dioxide and bicarbonate, so each gas is physiologic;
  - the Winter formula (1.5 x bicarbonate + 8, plus or minus 2) is NOT given in the stem; the respiratory acidosis
    ratios (1 acute, 3.5 chronic per 10 mm Hg) and the metabolic alkalosis ratio (0.75 per 1 mEq/L) ARE given, from
    the stated baselines of 40 mm Hg and 25 mEq/L;
  - Winter items use bicarbonate values where the s24 "1.3 per 1" rule lands on the same side, and every measured
    carbon dioxide sits at least 3 mm Hg outside the predicted range (or inside it, for "appropriate");
  - change in gap = gap - 10, change in bicarbonate = 25 - measured (the size of the fall; the sign is never asked);
  - no normal chloride baseline is on a slide, so the chloride check is asked as "examine the change in chloride"
    with a chloride above its range, never as a computed number;
  - metabolic acidosis plus metabolic alkalosis items ask about the metabolic processes only (their bicarbonate sits
    where the Winter formula and the 1.3 rule disagree);
  - diabetic ketoacidosis items name the phase (s45 vs s47); no raised gap sits at 13-20 with a "is it primary" ask;
    pH never above 7.6; no patient or value from the lecturer's off-deck cases A and B; s28-30 example values are
    not reused.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e7l45_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


def ABG(ph, pco2, hco3):
    return "Arterial blood gas: " + gas(ph, pco2, hco3)


def NACL(na, cl):
    return "sodium %s mEq/L %s, chloride %s mEq/L %s" % (na, NA, cl, CL)


def ALBV(a):
    return "albumin %s g/dL %s" % (a, ALB)


BASE = "From a baseline carbon dioxide of 40 mm Hg and bicarbonate of 25 mEq/L, "
MALK = "in metabolic alkalosis carbon dioxide rises 0.75 mm Hg per 1 mEq/L rise in bicarbonate"
RACH = "in chronic respiratory acidosis bicarbonate rises 3.5 mEq/L per 10 mm Hg rise in carbon dioxide"
RACU = "in acute respiratory acidosis bicarbonate rises 1 mEq/L per 10 mm Hg rise in carbon dioxide"
DELTA = "Using 10 as the normal anion gap and 25 mEq/L as the normal bicarbonate, "

